"""Apply the reviewed TAKERU catalogue source diff, then remove this one-shot helper."""
import base64, subprocess, zlib
from pathlib import Path
PATCH = ""
raw = zlib.decompress(base64.b64decode(PATCH))
subprocess.run(['git', 'apply', '--check', '-'], input=raw, check=True)
subprocess.run(['git', 'apply', '-'], input=raw, check=True)
Path('scripts/_apply_takeru_completion_20261028.py').unlink()
Path('.github/workflows/_takeru_completion_20261028.yml').unlink()
